components.css:
.ds-theme-selector{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.ds-theme-selector {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  display: inline-flex;
  gap: 10px;
  margin: 0;
  min-inline-size: 0;
  padding: 3px 3px 3px 12px;
}

.ds-theme-legend {
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.ds-theme-label {
  color: var(--color-muted);
  font-size: 12px;
  white-space: nowrap;
}

.ds-theme-options {
  display: flex;
  gap: 2px;
}

.ds-theme-option {
  cursor: pointer;
  position: relative;
}

.ds-theme-option input {
  cursor: pointer;
  height: 100%;
  inset: 0;
  margin: 0;
  opacity: 0;
  position: absolute;
  width: 100%;
}

.ds-theme-option span {
  align-items: center;
  border: 1px solid transparent;
  border-radius: 3px;
  color: var(--color-text);
  display: flex;
  font-size: 12px;
  font-weight: 650;
  justify-content: center;
  min-height: var(--control-height);
  min-width: 50px;
  padding: 0 10px;
}

.ds-theme-option:hover span {
  background: var(--color-surface-muted);
  border-color: var(--color-primary);
}

.ds-theme-option input:checked + span {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-primary-ink);
}

.ds-theme-option:hover input:checked + span {
  background: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

.ds-theme-option input:focus-visible + span {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

@media (max-width: 900px), (pointer: coarse) {
  .ds-theme-option span {
    min-height: 44px;
  }
}

@media (forced-colors: active) {
  .ds-theme-option input:checked + span {
    border-color: Highlight;
    outline: 2px solid Highlight;
    outline-offset: -3px;
  }
}
@media(max-width:767px) and (min-height:501px),(max-width:539px){.ds-theme-selector{padding-left:3px;gap:0}.ds-theme-label{display:none}}
